8: function superellipseRing(w, h, count, power = 0.62) {
9:   const pts = [];
10:   for (let i = 0; i < count; i++) {
11:     const t = (i / count) * TAU;
12:     const c = Math.cos(t);
13:     const s = Math.sin(t);
14:     pts.push({
15:       x: Math.sign(c) * Math.pow(Math.abs(c), power) * w,
16:       y: Math.sign(s) * Math.pow(Math.abs(s), power) * h
17:     });
18:   }
19:   return pts;
20: }
