22: function loft(sections, material, { radial = 14, power = 0.62 } = {}) {
23:   const positions = [];
24:   const indices = [];
25:   const rings = sections.map((s) => superellipseRing(s.w, s.h, radial, power).map((p) => [p.x, s.y + p.y, s.z]));
26:   for (let i = 0; i < rings.length; i++) {
27:     const ring = rings[i];
28:     for (const p of ring) positions.push(...p);
29:   }
30:   for (let i = 0; i < rings.length - 1; i++) {
31:     for (let j = 0; j < radial; j++) {
32:       const a = i * radial + j;
33:       const b = i * radial + ((j + 1) % radial);
34:       const c = (i + 1) * radial + j;
35:       const d = (i + 1) * radial + ((j + 1) % radial);
36:       indices.push(a, c, b, b, c, d);
37:     }
38:   }
39:   // caps
40:   const firstCenter = positions.length / 3;
41:   positions.push(0, sections[0].y, sections[0].z);
42:   for (let j = 0; j < radial; j++) {
43:     indices.push(firstCenter, j, (j + 1) % radial);
44:   }
45:   const lastBase = (rings.length - 1) * radial;
46:   const lastCenter = positions.length / 3;
47:   positions.push(0, sections[sections.length - 1].y, sections[sections.length - 1].z);
48:   for (let j = 0; j < radial; j++) {
49:     indices.push(lastCenter, lastBase + ((j + 1) % radial), lastBase + j);
50:   }
51:   const geo = new THREE.BufferGeometry();
52:   geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
53:   geo.setIndex(indices);
54:   geo.computeVertexNormals();
55:   const mesh = new THREE.Mesh(geo, material);
56:   mesh.castShadow = true;
57:   return mesh;
58: }
