60: function topStripe(sections, width, material) {
61:   const positions = [];
62:   const indices = [];
63:   const half = width / 2;
64:   sections.forEach((s, i) => {
65:     const y = s.y + s.h + 0.012;
66:     positions.push(-half, y, s.z, half, y, s.z);
67:     if (i > 0) {
68:       const a = (i - 1) * 2;
69:       indices.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
70:     }
71:   });
72:   const geo = new THREE.BufferGeometry();
73:   geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
74:   geo.setIndex(indices);
75:   geo.computeVertexNormals();
76:   const mesh = new THREE.Mesh(geo, material);
77:   mesh.castShadow = false;
78:   return mesh;
79: }
